sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-21: vehicle from reservation, overall_pass, one CHECK_OUT / CHECK_IN per reservation and vehicle
    if (current.vehicle.nil() && !current.reservation.nil() && !current.reservation.assigned_vehicle.nil()) {
        current.setValue('vehicle', current.reservation.assigned_vehicle.toString());
    }

    var pass = current.tire_pressure_ok == true && current.lights_ok == true && current.windshield_ok == true;
    current.setValue('overall_pass', pass);

    if (current.operation() == 'insert' || current.reservation.changes() || current.vehicle.changes() ||
        current.inspection_type.changes()) {
        var dup = new GlideRecord('x_1850693_enterp_0_inspection');
        dup.addQuery('reservation', current.getValue('reservation'));
        dup.addQuery('vehicle', current.getValue('vehicle'));
        dup.addQuery('inspection_type', current.getValue('inspection_type'));
        dup.addQuery('sys_id', '!=', current.getUniqueValue());
        dup.setLimit(1);
        dup.query();
        if (dup.hasNext()) {
            gs.addErrorMessage('A ' + current.inspection_type.getDisplayValue() +
                ' inspection already exists for this reservation and vehicle.');
            current.setAbortAction(true);
        }
    }
})(current, previous);
